INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136437, 'spa', 'Maldad, mal moral — la cualidad abstracta de la perversidad en la conducta human', 'Maldad, mal moral — la cualidad abstracta de la perversidad en la conducta humana, presente abrumadoramente en la acusación profética ''la maldad de vuestras obras'' (רֹעַ מַעַלְלֵיכֶם). Dieciséis ocurrencias abarcan desde Deuteronomio hasta Oseas: Dios amenaza con enviar maldiciones ''por la maldad de vuestras obras'' (Dt 28:20), Isaías ordena ''quitad la maldad de vuestras obras de ante mis ojos'' (Is 1:16) y Jeremías repite la fórmula como estribillo del juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136440, 'spa', 'Tristeza, desagrado del semblante — significado afectivo especializado, distinto', 'Tristeza, desagrado del semblante — significado afectivo especializado, distinto del mal moral. Dos ocurrencias captan este matiz: Nehemías 2:2, donde el rey pregunta ''¿por qué está triste tu rostro?'' (רֹעַ פָּנִים), y Eclesiastés 7:3, ''con la tristeza del rostro se enmienda el corazón''. Aquí el vocabulario pasa del ámbito moral al emocional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136441, 'spa', 'Mala calidad, fealdad — deficiencia física o apariencia desagradable, describien', 'Mala calidad, fealdad — deficiencia física o apariencia desagradable, describiendo la maldad exterior en lugar del carácter moral. Una ocurrencia clara en Génesis 41:19, donde el faraón recuerda ''subieron tras ellas otras siete vacas, flacas y muy feas — nunca he visto tal fealdad (רֹעַ) en toda la tierra de Egipto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136444, 'spa', 'Tener hambre, experimentar hambre — el sentido Qal intransitivo que describe el ', 'Tener hambre, experimentar hambre — el sentido Qal intransitivo que describe el estado o condición de hambre en todas las personas y tiempos verbales. Las 11 ocurrencias abarcan diversos géneros: narrativa (''toda la tierra de Egipto padecía hambre'', Gn 41:55), salmo (''los leoncillos necesitan y tienen hambre'', Sal 34:10; ''si yo tuviese hambre, no te lo diría'', Sal 50:12), promesa y amenaza profética (''no tendrán hambre ni sed'', Is 49:10; ''vosotros tendréis hambre'', Is 65:13) y sabiduría (''el alma del perezoso pasa hambre'', Pr 19:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136445, 'spa', 'Causar hambre, hacer o dejar que alguien pase hambre — la forma Hifil (causativa', 'Causar hambre, hacer o dejar que alguien pase hambre — la forma Hifil (causativa), donde el sujeto inflige hambre sobre otro. Solo 2 ocurrencias, pero ambas cargadas teológicamente. Deuteronomio 8:3 es el texto clave: Dios ''te hizo pasar hambre y te alimentó con maná'', una pedagogía divina deliberada donde el hambre precede a la provisión para enseñar dependencia — el mismo versículo que Jesús cita al ser tentado en el desierto (Mt 4:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136457, 'spa', 'Hambriento o famélico, describe a personas privadas de alimento, usado tanto com', 'Hambriento o famélico, describe a personas privadas de alimento, usado tanto como adjetivo como sustantivo (''los hambrientos''). Aparece en contextos de extrema necesidad física junto a ''sediento'' y ''agotado'' (2 Sam 17:29; 2 Re 7:12; Sal 107:5), en llamados proféticos a la justicia — alimentar al hambriento como acto de rectitud (Isa 58:7, 10; Ez 18:7, 16), retener el alimento como maldad (Job 22:7) — y en la teología de la inversión divina donde los hambrientos dejan de tener hambre (1 Sam 2:5). Un notable uso figurado aparece en Job 18:12, donde la fuerza de un hombre ''pasa hambre'', es decir, se consume.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136468, 'spa', 'hambruna (escasez general)', 'Escasez prolongada y grave de alimentos que aflige a una tierra o región, a menudo una hambruna histórica que impulsa la narrativa bíblica. Las hambrunas patriarcales (Gn 12:10; 26:1; 41:27-57), la del reinado de David (2 S 21:1) y las de asedio en Reyes y Jeremías emplean רָעָב así. Alemán Hungersnot y español el hambre captan este sentido colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136473, 'spa', 'hambre (sensación física)', 'La sensación física personal de tener hambre, o la inanición como sufrimiento individual. Dt 28:48 la empareja con la sed como disciplina del pacto; Is 5:13 y Lm 5:10 describen el hambre consumiendo a las personas. Alemán Hunger (sin -not) y español de hambre (partitivo) reflejan el desplazamiento de un acontecimiento social a un estado corporal individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136483, 'spa', 'hambre o hambruna severa', 'La palabra se refiere a hambre severa o escasez a nivel de hambruna. En Génesis 42:19 y 33, José manda a sus hermanos llevar grano de vuelta ''para el hambre de vuestras casas''—las condiciones de hambruna que impulsaban sus repetidos viajes a Egipto para sobrevivir. Salmo 37:19 promete que los justos serán saciados ''en días de hambre,'' usando el término para tiempos cuando la escasez de alimentos amenaza la vida. A diferencia del hambre ordinaria, este término denota crisis alimentaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136484, 'spa', 'temblar por circunstancias abrumadoras', 'El término captura la respuesta de temblor ante circunstancias abrumadoras. Salmo 104:32 lo usa en teofanía: ''Él mira a la tierra, y ella tiembla''—la creación misma estremeciéndose ante la mirada del Creador. Daniel 10:11 describe el estado físico del profeta después de la visión: ''me puse en pie temblando,'' incapaz de funcionar normalmente tras encontrar al mensajero angelical. Esdras 10:9 retrata a la asamblea reunida sentada y temblando bajo la lluvia, sobrecogida por su transgresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136487, 'spa', 'temblor por miedo reverente', 'La palabra designa el estremecimiento físico que acompaña temor intenso o reverencia. Salmo 2:11 manda ''Servid a Jehová con temor, y alegraos con temblor''—el temblor como postura apropiada ante la soberanía divina. Salmo 48:6 (verso hebreo 7) describe temblor apoderándose de reyes enemigos: ''Les sobrecogió allí temor, dolor como de mujer de parto,'' comparando su pánico con dolores de alumbramiento. Isaías 33:14 retrata a pecadores en Sion presa de temblor temeroso ante el fuego santo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136489, 'spa', 'pastor (sustantivo agente)', 'Participio activo Qal usado como sustantivo agente: ''pastor, ganadero.'' Con 76 apariciones es el uso más frecuente, funcionando como sustantivo independiente. Aparece en singular y plural, masculino y femenino (Raquel como רֹעָה en Gn 29:9), en cadenas constructas (''pastores de Israel,'' Ez 34:2) y con artículo. Las lenguas cognadas confirman el patrón agentivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136494, 'spa', 'pastorear, apacentar', 'Sentido verbal transitivo: pastorear, apacentar un rebaño o, metafóricamente, un pueblo. El sujeto es el pastor que actúa sobre el rebaño como objeto. Abarca todas las conjugaciones finitas —perfecto, imperfecto, imperativo, infinitivo— en 60 apariciones. El español apacentar distingue con nitidez este sentido del pacer intransitivo. Pasajes clave incluyen Ezequiel 34 y el Salmo 23.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136497, 'spa', 'pacer, alimentarse', 'Sentido intransitivo: pacer o alimentarse, con el animal como sujeto en lugar de un pastor humano. Se distingue interlingüísticamente por el español pacer/pastar (frente al transitivo apacentar). Las 17 apariciones describen vacas paciendo junto al Nilo (Gn 41:2, 18), ganado alimentándose cerca del Sinaí (Éx 34:3) y animales en el prado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136526, 'spa', 'devorar, consumir (figurado)', 'Extensión figurada-destructiva donde ''alimentarse de'' se convierte en ''devorar'' o ''consumir'' con efecto dañino. Solo 3 apariciones, pero vívidamente distintas: el jabalí que «devora» la vid en el Salmo 80:13, la descripción del malvado que «se alimenta de» la estéril en Job 24:21 (es decir, la explota), y Jeremías 2:16. La imagen pastoril se invierte en destrucción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136582, 'spa', 'Asociarse, acompañar', 'Asociarse con alguien, ser compañero o amigo, entablar una relación estrecha. El participio Qal רֹעֶה funciona como ''el que se junta con'' en las advertencias sapienciales de Proverbios: necios (13:20), glotones (28:7) y prostitutas (29:3). El vocabulario es relacional, no pastoral. Prov 22:24 extiende la advertencia a los iracundos, confirmando el campo semántico de compañerismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136583, 'spa', 'Pacer, apacentar', 'Pacer, alimentar o apacentar en sentido pastoral-agrícola, solapándose con la mucho más frecuente רָעָה I (pastorear). En Salmo 37:3, el imperativo ''apacienta la fidelidad'' emplea esta raíz. Isaías 11:7 describe a la vaca y al oso paciendo juntos. El español distingue ambos pasajes con ''apacienta'' (cuida/alimenta) y ''pacerán'' (pastarán).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136587, 'spa', 'Amigo o consejero', 'Designa a un amigo, con uso especializado como titulo real. La expresion tecnica רֵעֶה הַמֶּלֶךְ (''el amigo del rey'') aparece en 1 Reyes 4:5 y 2 Samuel 15:37, 16:16 como ''amigo de David'', un cargo formal de la corte, probablemente un consejero de confianza. Proverbios 27:10 lo emplea en sentido relacional simple: ''el amigo de tu padre''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136590, 'spa', 'nombre propio patriarcal', 'El nombre propio Reú, patriarca en la línea de Sem, hijo de Péleg y padre de Serug (Gn 11:18-21; 1 Cr 1:25). Todas las apariciones son estrictamente genealógicas, situando a Reú en la generación puente entre los patriarcas antediluvianos y Abraham. La Septuaginta lo transcribe como Ραγαύ. Posiblemente relacionado con la raíz רָעָה (''amigo, compañero'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136591, 'spa', 'Reuel (nombre propio)', 'Nombre propio masculino que significa ''amigo de Dios,'' aplicado a múltiples individuos: el hijo de Esaú a través de Basemat y ancestro de clanes edomitas (Gn 36:4, 10, 13, 17), el suegro madianita de Moisés que era sacerdote de Madián (Éx 2:18), y figuras en las genealogías de Gad y Benjamín (Nm 10:29; 1 Cr 9:8). El elemento teofórico se conserva en diversas tradiciones lingüísticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136593, 'spa', 'Compañera, prójima', 'Compañera, vecina o par femenina: una mujer en relación con otra mujer, ya sea como vecina, prójima o contraparte emparejada. Siempre aparece con sufijo de tercera persona femenina singular (''su compañera''). Se usa para israelitas que piden a sus vecinas egipcias (Éx 11:2), mujeres que enseñan lamentos (Jer 9:20), y aves emparejadas en la desolación (Isa 34:15-16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136597, 'spa', 'Afán, persecución vana', 'Afán o persecución vana, la fútil carrera tras el viento que Qohélet identifica como carácter último del esfuerzo humano bajo el sol. Usado exclusivamente en Eclesiastés en la frase re''ut ruach junto a hevel (Ecl 1:14; 2:11, 17, 26; 4:4, 6; 6:9), encapsula la tesis central del libro: que el esfuerzo sin referencia eterna equivale a intentar atrapar la brisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136601, 'spa', 'Pastor, ganadero', 'Pastor o ganadero: quien apacienta y cuida el ganado, usado tanto en sentido literal como en poderosa metáfora. En los relatos patriarcales designa a pastores de oficio (Gn 13:7-8; 26:20; 1 S 21:8). Teológicamente se convierte en título de Dios mismo (Sal 23:1) y de gobernantes comisionados por Dios como Ciro (Is 44:28) y el pastor herido de Zacarías 13:7.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136609, 'spa', 'Amada, compañera íntima', 'Compañera femenina amada, usada como término de tratamiento íntimo del amante hacia la mujer que atesora. Las nueve apariciones en el Cantar de los Cantares (1:9, 1:15, 2:2, 2:10, 2:13, 4:1, 4:7, 5:2, 6:4) figuran en el discurso directo del amante, presentando a la mujer no como mero objeto de deseo sino como compañera e igual. La evidencia multilingüe es reveladora: el español oscila entre ''amada mía'' y ''amiga mía''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136610, 'spa', 'afán o preocupación mental', 'La palabra designa el afán mental o vejación que caracteriza la existencia humana bajo el sol. Eclesiastés 1:17 describe perseguir sabiduría como ''afán tras el viento''—asir lo que elude el control. Eclesiastés 2:22 pregunta qué obtiene el hombre de todo su trabajo ''y del afán de su corazón''—la ocupación ansiosa de mente que acompaña la labor. Eclesiastés 4:16 concluye reflexiones sobre popularidad declarando que también es vanidad y ''afán tras el viento.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136611, 'spa', 'Pensamiento, reflexión', 'Pensamiento, reflexión, cogitación — la actividad mental de pensar, meditar o estar turbado en el ánimo. Se encuentra exclusivamente en las secciones arameas de Daniel, siempre en plural y con posesivo (''tus pensamientos'', ''sus pensamientos'', ''mis pensamientos''). Los pensamientos de Nabucodonosor surgen en su lecho acerca del futuro (Dan 2:29) y Dios los revela a través de Daniel (Dan 2:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136619, 'spa', 'Hifil', 'Hifil: tronar. El causativo Hifil: Dios produce el trueno o truena con fuerza. Es el sentido más frecuente, abarcando contextos teofánicos donde el trueno divino señala poder, juicio o autoridad cósmica. En Mizpa (1 Sam 7:10) el SEÑOR tronó y puso en fuga a los filisteos; en el Salmo 29:3 la ''voz del SEÑOR'' truena sobre las aguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136621, 'spa', 'Qal', 'Qal: rugir, bramar. El Qal intransitivo: el mar o la naturaleza ruge, brama, produce un gran estruendo en alabanza. Se encuentra exclusivamente en los salmos de alabanza a la creación (Sal 96:11; 98:7; 1 Cr 16:32) donde el mar se une a la aclamación del SEÑOR junto con el regocijo, el aplauso y el canto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136625, 'spa', 'Qal', 'Qal: estar perturbado, agitado. Un uso estativo del Qal que significa estar turbado, agitado o convulso, atestiguado una vez en Ezequiel 27:35, donde los rostros de los reyes que presencian la caída catastrófica de Tiro se describen como temblorosos. El BDB señala que la etimología es debatida; la LXX y la Peshitta sugieren una enmienda a ''sus rostros lloraron''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136626, 'spa', 'Hifil', 'Hifil: hacer temblar, provocar. El Hifil en un sentido emocional transferido: causar que alguien tiemble o provocar agitación. Atestiguado una vez en 1 Samuel 1:6, donde Penina provoca a Ana hasta la angustia por su esterilidad. Las glosas multilingües muestran que los traductores leen esto como un tormento emocional deliberado y causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136629, 'spa', 'Trueno', 'Trueno como fenómeno natural y teofánico, siempre atribuido al poder y majestad de Yahvé. Aparece en contextos de autorrevelación divina (Sal 81:7, ''en el lugar secreto del trueno''), autoridad cósmica sobre la creación (Sal 104:7, ante la reprensión de Dios las aguas huyeron) y como figura del poder abrumador (Job 26:14, el ''trueno de su poder'' es solo el borde de sus caminos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136635, 'spa', 'nombre propio étnico', 'El nombre propio Raamá, nieto de Cam a través de Cus en la Tabla de las Naciones (Gn 10:7; 1 Cr 1:9), que representa un pueblo del sur de Arabia dedicado al comercio de lujo. Ezequiel 27:22 lo ubica entre los socios mercantiles de Tiro que comerciaban con especias, gemas y oro, vinculándolo con las rutas del incienso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136637, 'spa', 'topónimo egipcio', 'El nombre propio Ramesés, ciudad egipcia en el delta oriental del Nilo nombrada en honor al faraón Ramsés II. Ancla geográfica del Éxodo: sede del trabajo forzado (Éx 1:11), punto de partida de la salida de Egipto (Éx 12:37; Nm 33:3, 5) y anteriormente la tierra donde José asentó a su familia (Gn 47:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136640, 'spa', 'Verde, frondoso u hojoso, describe árboles en su máximo esplendor de follaje', 'Verde, frondoso u hojoso, describe árboles en su máximo esplendor de follaje. Domina la frase formulaica ''debajo de todo árbol frondoso'' (kol-ets ra''anan), que se repite a lo largo de Deuteronomio, Reyes, Crónicas, Jeremías, Isaías y Ezequiel como marca estándar de sitios de culto cananeo. También se aplica al lecho verde y exuberante del Cantar de los Cantares 1:16, fusionando la imaginería botánica con la intimidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136644, 'spa', 'Fresco, lleno de savia, vigoroso — usado figuradamente de personas que permanece', 'Fresco, lleno de savia, vigoroso — usado figuradamente de personas que permanecen vitalmente vivas, especialmente en la vejez. En el Salmo 92:14 los justos ''aún en la vejez fructifican; están llenos de savia y frondosos (ra''anan)''. Este sentido transfiere el verdor perenne del árbol a personas que prosperan bajo el cuidado de Dios, creando un puente semántico entre el mundo botánico y la vida espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136648, 'spa', 'Participio Hifil sustantivado', 'Participio Hifil sustantivado: malhechor, el que hace el mal. Funciona como sustantivo que designa a una persona caracterizada por la maldad habitual. Término clave en los Salmos (22:16, 26:5, 37:1, 37:9) y Proverbios, a menudo contrastado con el justo. La forma participial porta un aspecto iterativo-habitual: no un solo acto malo sino un patrón de conducta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136650, 'spa', 'Hifil activo', 'Hifil activo: hacer el mal, actuar con maldad, causar daño o tratar mal a alguien. Es el sentido dominante, que cubre la maldad volitiva en textos narrativos, proféticos y legales. La opresión de Faraón contra Israel (Éx 5:23), el engaño de Labán a Jacob (Gn 31:7) y la advertencia general contra hacer el mal (Jer 4:22, 13:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136651, 'spa', 'Qal estativo', 'Qal estativo: ser malo, resultar desagradable, típicamente en la expresión «fue malo a los ojos de». Describe un estado de desagrado o tristeza más que una acción: algo aflige o entristece a una persona. Abraham se angustia (Gn 21:11-12), Samuel se disgusta (1 S 8:6), el rostro de Nehemías se entristece (Neh 2:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136658, 'spa', 'Nifal/Qal pasivo o tolerativo', 'Nifal/Qal pasivo o tolerativo: sufrir daño, ser perjudicado. Matiz poco frecuente que se encuentra en Proverbios (11:15, 13:20), donde el sujeto experimenta consecuencias malas en lugar de perpetuar el mal: «el que sale fiador sufrirá daño». Marca esta dimensión pasiva-experiencial claramente distinta del Hifil activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136679, 'spa', 'Una única aparición en 2 S 19', 'Una única aparición en 2 S 19:7 donde la forma verbal parece funcionar como intensificador comparativo: el mal «será peor para ti que todo el mal que te ha sobrevenido». Se entiende mejor como una extensión del sentido Qal estativo (sentido 2) aplicado en una construcción comparativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136711, 'spa', 'Quebrarse, hacerse pedazos', 'Qal intransitivo y Hitpael reflexivo: quebrarse, hacerse pedazos. Isaías 24:19 repite la raíz en un dramático énfasis triple — «la tierra se quiebra por completo» —, mientras que Jeremías 11:16 lo usa para ramas que se quiebran en el fuego. En Isaías 8:9, el imperativo Hitpael («¡quebrantaos, pueblos!») funciona como un desafío profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136713, 'spa', 'Arruinarse, destruirse', 'Hitpael figurado: arruinarse, atraer la destrucción sobre uno mismo. Atestiguado en Proverbios 18:24, donde el hombre de muchos compañeros «se arruina» (lehitroʿeaʿ). El quebrantamiento aquí es social y moral, no físico: las relaciones superficiales en exceso conducen a la autodestrucción. Se retiene la cualidad pasivo-reflexiva de este colapso figurado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136714, 'spa', 'Quebrantar, destrozar', 'Qal transitivo: quebrantar o destrozar algo, con un agente que actúa sobre un objeto. Salmo 2:9 es el pasaje definitorio: «Los quebrantarás con vara de hierro» (teroʿem), una imagen regio-mesiánica. Job 34:24 lo extiende al juicio divino: Dios «quebranta a los poderosos». Jeremías 15:12 plantea la pregunta retórica de si el hierro puede quebrar el hierro del norte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136720, 'spa', 'Gotear, destilar', 'Gotear, destilar o chorrear suavemente — describe el descenso sostenido de humedad (lluvia, rocío, abundancia) desde los cielos a la tierra. Job 36:28 lo aplica a nubes que gotean lluvia, Proverbios 3:20 a cielos que destilan rocío y Salmo 65:11-12 a sendas divinas que rebosan. Isaías 45:8 eleva la imagen a metáfora profética, mandando a los cielos destilar justicia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136722, 'spa', 'El sentido central en Qal de temblar o estremecerse, que describe típicamente la', 'El sentido central en Qal de temblar o estremecerse, que describe típicamente la tierra, los montes o los cimientos sacudiéndose ante una teofanía, un juicio divino o un evento catastrófico. La tierra tembló cuando Dios marchó desde Seír (Jue 5:4), se estremeció al soplo de su nariz (2 Sam 22:8 / Sal 18:7) y temblará cuando caigan las naciones (Jer 49:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136725, 'spa', 'El significado causativo en Hifil', 'El significado causativo en Hifil: hacer temblar o sacudir, con Dios como agente típico. El Salmo 60:2 lamenta ''Tú hiciste temblar la tierra,'' Isaías 14:16 se asombra del tirano que ''hacía estremecer la tierra,'' y Hageo 2:6–7 promete que Dios hará temblar los cielos, la tierra, el mar y las naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136730, 'spa', 'Un uso único en Qal en el Salmo 72', 'Un uso único en Qal en el Salmo 72:16 que describe el ondear o mecerse del grano abundante en la cima de los montes — una imagen mesiánica de bendición agrícola tan grande que las cumbres se mecen como los cedros del Líbano. La misma raíz que transmite fuerza sísmica aterradora aquí evoca el movimiento rítmico y suave de una cosecha abundante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136731, 'spa', 'Un uso singular en Hifil en Job 39', 'Un uso singular en Hifil en Job 39:20 que significa hacer saltar o brincar a un animal, aplicado al caballo de guerra que Dios ha dotado de poder aterrador. La pregunta retórica ''¿Lo haces saltar como langosta?'' emplea la raíz del temblor para transmitir un movimiento explosivo y elástico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136746, 'spa', 'Terremoto literal — sacudida sísmica del suelo', 'Terremoto literal — sacudida sísmica del suelo. El famoso terremoto de Amós 1:1 y Zacarías 14:5, el temblor teofánico en Horeb (1 Re 19:11-12) y la conmoción escatológica de Ezequiel 38:19 e Isaías 29:6 emplean este sentido. La evidencia interlingüística es notablemente consistente: ''terremoto'' (esp.), ''Erdbeben'' (ale.), ''지진'' (cor.).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136748, 'spa', 'Un estruendo fuerte o ruido atronador, frecuentemente asociado con las ruedas de', 'Un estruendo fuerte o ruido atronador, frecuentemente asociado con las ruedas de carros de guerra (Nah 3:2, Jer 47:3) o el sonido imponente de la gloria divina en movimiento (Ez 3:12-13). La dimensión acústica predomina aquí sobre el movimiento físico, enfocándose en el impacto auditivo más que en la vibración material.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136749, 'spa', 'Sacudida violenta, temblor o conmoción que no es necesariamente sísmica — el tra', 'Sacudida violenta, temblor o conmoción que no es necesariamente sísmica — el traqueteo de una lanza que vibra (Job 41:29), la agitación de un caballo de guerra (Job 39:24) o el estremecimiento de personas aterradas (Ez 12:18). Isaías 9:5 lo emplea para el tumulto de la batalla, diferenciándolo de un terremoto propiamente dicho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136759, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser sanado, curarse o recuperarse. Diecisiete apariciones describen al sujeto siendo sanado, particularmente en las regulaciones levíticas sobre enfermedades de la piel donde el sacerdote observa si la aflicción «ha sido sanada» (Lv 13:18, 37; 14:3, 48). Is 53:5, «por sus heridas fuimos sanados», es la cumbre teológica de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136760, 'spa', 'Qal activo', 'Qal activo: sanar, curar o restaurar la salud, con Dios o un agente humano como sujeto. Cubre 30 apariciones en formas finitas, infinitivos e infinitivo absoluto. Pasajes clave incluyen a Dios sanando la casa de Abimelec (Gn 20:17) y la oración de Ezequías pidiendo sanidad (2 R 20:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136761, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: sanarse a sí mismo o buscar curación para sí. Tres apariciones se agrupan en torno al rey Joram que fue a Jezreel «para curarse» de las heridas recibidas en batalla (2 R 8:29; 9:15; 2 Cr 22:6). La forma reflexiva distingue la recuperación autodirigida de la sanidad administrada por otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136764, 'spa', 'Participio activo Qal usado como sustantivo', 'Participio activo Qal usado como sustantivo: médico, sanador. Ocho apariciones incluyen a los médicos egipcios que embalsamaron a Jacob (Gn 50:2), la autodesignación de Dios como «tu sanador» (Éx 15:26) y el fracaso de Asa al buscar a los médicos en lugar del Señor (2 Cr 16:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136769, 'spa', 'Piel intensivo', 'Piel intensivo: tratar médicamente, sanar a fondo o de manera decisiva. Nueve apariciones enfatizan la completitud o el cuidado profesional. Éx 21:19 exige que el agresor asegure que la víctima sea «completamente sanada». La crítica mordaz de Jeremías de que los falsos profetas «han curado la herida de mi pueblo superficialmente» (Jer 6:14; 8:11) usa el Piel para denunciar el tratamiento superficial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136784, 'spa', 'Sentido extendido que significa reparar o restaurar una estructura física, no un', 'Sentido extendido que significa reparar o restaurar una estructura física, no un cuerpo humano. En 1 R 18:30 Elías «reparó» el altar del SEÑOR que había sido derribado. El hebreo רָפָא tiende un puente entre la sanidad corporal y la restauración estructural, haciendo eco del sentido árabe de zurcir y remendar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136793, 'spa', 'Aparición del Nifal en Jer 19', 'Aparición del Nifal en Jer 19:11 donde una vasija de alfarero es quebrada sin posibilidad de ser «reparada» o restaurada. Extiende la metáfora de sanidad a la rotura irreparable, una poderosa imagen profética de juicio. Aplica רָפָא a objetos en lugar de personas, pero enfatiza la imposibilidad de restauración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136812, 'spa', 'Sombras, espíritus difuntos', 'Las sombras o espíritus difuntos que habitan el Seol, concebidos como restos débiles y espectrales de los vivos. Etimológicamente conectado a una raíz que sugiere debilidad o hundimiento, el término retrata a los muertos como seres impotentes. Pasajes clave: Job 26:5, donde los refaim tiemblan bajo las aguas; Proverbios 2:18 y 9:18, donde acechan en el camino de la insensatez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136818, 'spa', 'El Rafá (ancestro gigante)', 'Nombre propio con artículo definido que designa la figura ancestral del clan de gigantes refaítas. Las seis apariciones se concentran en el ciclo narrativo de 2 Samuel 21 y su paralelo en 1 Crónicas 20, donde guerreros filisteos de tamaño extraordinario son identificados como ''nacidos del Rafá'' (יְלִידֵי הָרָפָה). La construcción funciona como patronímico del clan.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136821, 'spa', 'El grupo étnico de los refaítas (רְפָאִים II), un pueblo antiguo de gran estatur', 'El grupo étnico de los refaítas (רְפָאִים II), un pueblo antiguo de gran estatura física que ocupaba Canaán y Transjordania antes de la llegada de Israel. Aparecen en el contexto de la Tabla de las Naciones (Gn 15:20), en el reino de Og en Basán (Dt 3:11; Jos 12:4) y en el Valle de Refaím cerca de Jerusalén (2 Sam 5:18, 22). El nombre es distinto del uso homónimo de la misma raíz que designa las ''sombras de los muertos''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136828, 'spa', 'remedios inútiles', 'La palabra se refiere a remedios medicinales o tratamientos curativos, siempre usada figuradamente para desastres nacionales. Jeremías 30:13 declara que Judá no tiene ''remedios para tu herida'', enfatizando la naturaleza incurable del juicio. Jeremías 46:11 se burla de Egipto: ''En vano has usado muchas medicinas; no hay curación para ti''—los remedios multiplicados resultan inútiles contra la invasión babilónica. Ezequiel 30:21 anuncia que el brazo de Faraón no será vendado ni sanado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136831, 'spa', 'extender y sostener', 'Las tres ocurrencias abarcan la extensión literal (el rastro del cocodrilo en el lodo) y el sustento figurado (ser refrescado/sostenido con fruta). El español usa ''extender'' (spread) y ''refrescar'' (refresh), mientras el francés emplea ''restaurer'' (restore/refresh), reflejando tanto las dimensiones físicas como restaurativas. Job 17:13 usa la forma pasada para describir extender una cama en el Seol, reforzando la imagen de preparar un lugar de descanso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136832, 'spa', 'Sentido reflexivo (Nifal/Hitpael) de mostrarse negligente o perezoso, una desidi', 'Sentido reflexivo (Nifal/Hitpael) de mostrarse negligente o perezoso, una desidia culpable mas que incapacidad. Exodo 5:8,17 expresa la acusacion del Faraon: ''¡sois flojos!'' Proverbios 18:9 vincula al negligente con el destructor. Josue 18:3 desafia a las tribus: ''¿Hasta cuando sereis negligentes?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136833, 'spa', 'Sentido Hifil de abandonar o desamparar, usado casi exclusivamente en promesas d', 'Sentido Hifil de abandonar o desamparar, usado casi exclusivamente en promesas divinas de fidelidad. Deuteronomio 4:31 asegura ''no te abandonara.'' El estribillo repetido cinco veces en Dt 31:6,8, Jos 1:5 y 1 Cr 28:20 forma una formula de seguridad pactual: el brazo de Dios no desfallece.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136834, 'spa', 'Sentido Piel de dejar caer o bajar fisicamente algo, la accion concreta y mecani', 'Sentido Piel de dejar caer o bajar fisicamente algo, la accion concreta y mecanica. Job 12:21 describe a Dios aflojando el cinturon de los poderosos. Ezequiel 1:24-25 representa a los seres vivientes bajando sus alas cuando habla la voz divina. El Piel intensifica la accion fisica: un descenso deliberado mas que un hundimiento pasivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136835, 'spa', 'Soltar, liberar o dejar en paz, principalmente en Hifil pero tambien en Qal', 'Soltar, liberar o dejar en paz, principalmente en Hifil pero tambien en Qal. Las traducciones multilingues convergen en ''dejar.'' Exodo 4:26 conserva un uso Qal notoriamente dificil donde la intervencion de Sefora hace que el SENOR lo ''deje ir.'' Deuteronomio 9:14 y Josue 10:6 muestran la fuerza imperativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136837, 'spa', 'Sentido intransitivo Qal de volverse flojo, debil o sin fuerzas', 'Sentido intransitivo Qal de volverse flojo, debil o sin fuerzas: manos, cuerpos o determinacion perdiendo vigor. Isaias 13:7 lo empareja con corazones derretidos ante la caida de Babilonia. Nehemias 6:9 revela la estrategia: ''sus manos desfallecerán de la obra.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136838, 'spa', 'Sentido Piel causativo de debilitar o desalentar activamente la moral de alguien', 'Sentido Piel causativo de debilitar o desalentar activamente la moral de alguien. Jeremias 38:4 acusa al profeta de ''debilitar las manos'' de los soldados. Esdras 4:4 describe a los adversarios debilitando al pueblo de Juda. El Piel senala accion deliberada: no estar debil, sino hacer debiles a otros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136842, 'spa', 'Sentido Hifil de cesar, detenerse o estar quieto', 'Sentido Hifil de cesar, detenerse o estar quieto. Salmo 46:10 produce el celebre ''Estad quietos y sabed que yo soy Dios.'' Salmo 37:8 aconseja cesar de la ira. 1 Samuel 15:16 tiene a Samuel ordenando a Saul que ''pare.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136851, 'spa', 'Sentido Qal de hundirse, declinar o amainar, aplicado a fenomenos fisicos mas qu', 'Sentido Qal de hundirse, declinar o amainar, aplicado a fenomenos fisicos mas que a la fuerza humana. Jueces 19:9 lo usa para el dia que declina hacia el atardecer. Isaias 5:24 compara el desplome de Israel con heno que se consume en la llama. Jueces 8:3 describe la ira de Efrain amainando tras la diplomacia de Gedeon.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136874, 'spa', 'Debil o flojo', 'Denota flojedad o debilidad. Numeros 13:18 pregunta si los habitantes de la tierra son ''fuertes o debiles'' (הֶחָזָק הוּא אִם־רָפֶה). 2 Samuel 17:2 describe a David como ''fatigado y de manos debiles'' (רְפֵה יָדַיִם), es decir, desmoralizado. Job 4:3 menciona haber ''fortalecido manos debiles'' (יָדַיִם רָפוֹת). Isaias 35:3 ordena ''fortalecer las manos debiles'' en un contexto de restauracion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136878, 'spa', 'Campamento de Refidim', 'Nombre propio Refidim, campamento de Israel en la región del Sinaí, memorable como el lugar donde se hizo brotar agua de la roca (Éx 17:1) y donde Israel combatió contra Amalec (Éx 17:8). Constituye la última parada antes del Sinaí mismo (Éx 19:2) y aparece en el itinerario de Números 33:14-15. La Septuaginta lo transcribe Ῥαφιδείν.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136879, 'spa', 'Nombre propio Refaías', 'Nombre propio Refaías (''Yah ha sanado''), aplicado a cinco individuos: un descendiente davídico (1 Cr 3:21), un comandante simeonita (4:42), un jefe isacarita (7:2), un benjaminita descendiente de Saúl (9:43, variante de Rafa en 8:37) y un gobernador postexílico que reparó la muralla de Jerusalén (Neh 3:9). La Septuaginta lo transcribe Ῥαφαΐα.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136885, 'spa', 'agua enturbiada', 'Los tres usos involucran agua que se vuelve turbia mediante pisoteo. Ezequiel 32:2 y 34:18 lo emplean para criticar a quienes enlodan recursos para otros, mientras Proverbios usa el participio pasivo para un manantial contaminado. El español ''enturbiar'' (make turbid) y el francés ''fouler'' (trample) capturan la acción destructiva de pisar. Las imágenes consistentemente involucran pisoteo físico que degrada la calidad del agua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136891, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser aceptado, ser aceptable — el sentido técnico sacrificial que determina si una ofrenda cumple el estándar requerido. Lv 1:4 estipula que el holocausto «será aceptado» a favor del adorador. Es vocabulario ritual del sistema levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136892, 'spa', 'Sentido central Qal', 'Sentido central Qal: complacerse en, deleitarse en. Gn 33:10 registra el alivio de Jacob al saber que Esaú se ha «complacido» con él; 1 Cr 28:4 celebra la elección de Judá y David por Dios como actos de agrado divino. El árabe raḍiya (''estar complacido'') converge aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136893, 'spa', 'Qal transitivo', 'Qal transitivo: aceptar favorablemente — el acto de recibir ofrendas, personas u oraciones con aprobación. Lv 26:41 advierte que la tierra no los aceptará hasta que se humillen; 2 S 24:23 expresa la esperanza de Arauna de que Dios acepte la ofrenda de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136894, 'spa', 'Uso teológico especializado', 'Uso teológico especializado: la tierra «disfrutando» o «pagando» sus años sabáticos perdidos durante el exilio (Lv 26:34, 43; 2 Cr 36:21). Las traducciones revelan el doble matiz — tanto descanso compensatorio como liquidación de deuda. Este sentido es exclusivo de la legislación del año sabático y su eco en Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136898, 'spa', 'En Job 20', 'En Job 20:10, el verbo adquiere el matiz de buscar o procurar favor: los hijos del impío «buscarán favor de los pobres» que explotaron. Captura la desesperada reversión de fortuna que describe Zofar, un sentido suplicante distinto del favor otorgado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136908, 'spa', 'Participio pasivo Qal que funciona como adjetivo', 'Participio pasivo Qal que funciona como adjetivo: favorecido, aceptable, bien considerado. Dt 33:24 bendice a Aser como «favorecido entre sus hermanos»; Est 10:3 describe a Mardoqueo como «aceptado por la multitud de sus hermanos». Confirma la fuerza adjetival participial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136918, 'spa', 'En 1 S 29', 'En 1 S 29:4, los comandantes filisteos preguntan cómo David podría «reconciliarse» con Saúl — usando רָצָה para el acto político de recuperar el favor de un soberano mediante la traición en el campo de batalla. Señala una dimensión interpersonal-política distinta de la aceptación cúltica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136938, 'spa', 'Favor, buena voluntad y mirada benevolente — el sentido dominante con 25 aparici', 'Favor, buena voluntad y mirada benevolente — el sentido dominante con 25 apariciones, que describe la disposición benévola de Dios o de un rey hacia un receptor. Dt 33:16 y 33:23 lo usan para la bendición divina, y los Salmos celebran repetidamente el רָצוֹן de YHWH como fuente de vida y protección: «en su favor está la vida» (Sal 30:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136939, 'spa', 'Aceptación de una ofrenda sacrificial ante Dios — 11 apariciones concentradas en', 'Aceptación de una ofrenda sacrificial ante Dios — 11 apariciones concentradas en la legislación sacerdotal de Éxodo y Levítico. La fórmula técnica לְרָצוֹן לִפְנֵי יהוה (''para aceptación ante el SEÑOR'') aparece por primera vez en Éx 28:38 para la diadema sacerdotal y se repite en Levítico: las ofrendas deben ser «para vuestra aceptación» (Lv 1:3; 19:5; 22:19-21, 29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136940, 'spa', 'Voluntad, deseo o propósito volitivo — 16 apariciones donde רָצוֹן designa lo qu', 'Voluntad, deseo o propósito volitivo — 16 apariciones donde רָצוֹן designa lo que alguien pretende o desea hacer. Gn 49:6 advierte contra el רָצוֹן obstinado de los hermanos; Neh 9:24 y 9:37 describen a gobernantes extranjeros actuando «conforme a su voluntad»; Dn 8:4 y 11:3, 16, 36 retratan a conquistadores imperiales obrando «según su voluntad».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136944, 'spa', 'Deleite, placer o aquello que produce satisfacción — 4 apariciones en Proverbios', 'Deleite, placer o aquello que produce satisfacción — 4 apariciones en Proverbios donde רָצוֹן describe lo que agrada a Dios como cuestión de gusto y deleite, más que como favor relacional o aceptación cúltica. Pr 11:1 declara que «la balanza falsa es abominación para el SEÑOR, pero la pesa justa es su deleite (רְצוֹנוֹ)»; 11:20 contrasta al «perverso de corazón» con el íntegro en sus caminos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136970, 'spa', 'Participio activo Qal funcionando como sustantivo agente', 'Participio activo Qal funcionando como sustantivo agente: ''asesino'' u ''homicida'', termino tecnico juridico en la legislacion de las ciudades de refugio. Numeros 35:6-34 emplea este participio mas de veinte veces para definir los derechos del homicida y la jurisdiccion del vengador de sangre, convirtiendolo en el termino central del derecho homicida en la Torah.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136973, 'spa', 'Formas finitas del Qal que significan asesinar o matar ilicitamente', 'Formas finitas del Qal que significan asesinar o matar ilicitamente. Exodo 20:13 y Deuteronomio 5:17 consagran la prohibicion en el Decalogo. Deuteronomio 4:42 extiende el verbo al homicidio involuntario, quien mata ''sin conocimiento'', mientras 1 Reyes 21:19 lo usa para el asesinato judicial de Nabot por Acab.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136975, 'spa', 'Infinitivo absoluto Qal usado como sustantivo verbal que designa el acto de ases', 'Infinitivo absoluto Qal usado como sustantivo verbal que designa el acto de asesinar, tipicamente en listas profeticas de violaciones del pacto. Oseas 4:2 cataloga los pecados de Israel: ''jurar, mentir, matar'', y Jeremias 7:9 pregunta: ''¿Robareis, matareis, adulterareis?'' El infinitivo absoluto situa el asesinato junto a otras transgresiones capitales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136980, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser asesinado o muerto, expresando la experiencia de la victima. Jueces 20:4 relata la concubina del levita que ''fue asesinada'', y Proverbios 22:13 presenta la excusa absurda del perezoso: ''sere asesinado en las calles'', donde la voz pasiva presta al reclamo su fuerza dramatica e ironica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136981, 'spa', 'Participio Piel como sustantivo agente intensivo', 'Participio Piel como sustantivo agente intensivo: el asesino habitual o que se define por matar. En 2 Reyes 6:32, Eliseo llama al rey ''este hijo de asesino'', e Isaias 1:21 lamenta que la ciudad fiel se convirtio en ramera: ''asesinos'' moran donde antes habitaba la justicia. El Piel marca el asesinato como rasgo definitorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136982, 'spa', 'Pual pasivo (pasivo intensivo)', 'Pual pasivo (pasivo intensivo): ser asesinado o masacrado en masa. Salmo 62:3 pregunta ''¿Hasta cuando asaltareis a un hombre? Todos vosotros sereis matados.'' El Pual transmite el destino violento que espera a quienes conspiran contra el justo, senalando no mera muerte sino matanza brutal y colectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136986, 'spa', 'Formas finitas Piel que expresan asesinato intensivo o repetido', 'Formas finitas Piel que expresan asesinato intensivo o repetido: matanza habitual y sistematica. Salmo 94:6 denuncia a quienes ''asesinan a la viuda y al extranjero'', y Oseas 6:9 acusa a los sacerdotes de confabularse para ''asesinar en el camino a Siquem''. El Piel intensifica el verbo hacia la violencia sistematica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136992, 'spa', 'Rezín (nombre propio)', 'Nombre propio del rey de Aram-Damasco durante la crisis siro-efraimita (c. 735 a.C.), quien se alió con Pécaj hijo de Remalías contra el rey Acaz de Judá (2 R 15:37; 16:5-9; Is 7:1, 4, 8; 8:6; 9:11). Su campaña motivó la señal profética del Emmanuel. Tiglat-pileser III de Asiria lo derrotó y capturó Damasco. El nombre también aparece entre los netineos (sirvientes del templo) que regresaron del exilio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136998, 'spa', 'Pavimento, suelo empedrado', 'Superficie pavimentada de piedra en atrios de templos y salones palaciegos, que marca espacios de significación ceremonial. En la visión de Ezequiel define el atrio exterior (Ez 40:17-18; 42:3); en la dedicación del templo de Salomón, Israel se postra sobre él (2 Cr 7:3); y en Susa está compuesto de piedras preciosas (Est 1:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137004, 'spa', 'Nombre propio', 'Nombre propio de רִצְפָּה hija de Ayá, concubina de Saúl. Aparece en 2 Samuel 3:7, donde Is-boset acusa a Abner de relaciones con ella (implicando una pretensión al poder real); y de manera prominente en 2 Samuel 21:8, 10-11, donde sus dos hijos figuran entre los siete descendientes de Saúl ejecutados por los gabaonitas para poner fin a una hambruna. Su devota vigilancia de los cadáveres conmovió a David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137005, 'spa', 'Aplastamiento o quebrantamiento físico básico en Qal activo', 'Aplastamiento o quebrantamiento físico básico en Qal activo. En 1 Samuel 12:3-4, Samuel desafía a Israel: ''¿A quién he aplastado?'' — una defensa legal de su integridad. Isaías 42:4 promete que el Siervo ''no será quebrantado'' hasta que establezca la justicia. El Qal preserva la acción física directa: un agente ejerciendo fuerza destructiva sobre otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137006, 'spa', 'Causativo Hifil', 'Causativo Hifil: provocar el aplastamiento de algo. Jueces 9:53 relata cómo una mujer dejó caer una piedra de molino sobre la cabeza de Abimelec, quebrándole el cráneo. Esta única ocurrencia preserva nítidamente la fuerza causativa — un agente causa el aplastamiento de otro mediante un instrumento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137007, 'spa', 'Participio pasivo que describe el estado de estar aplastado o magullado — usado ', 'Participio pasivo que describe el estado de estar aplastado o magullado — usado adjetivalmente. La icónica ''caña quebrada'' de Isaías 42:3 y 2 Reyes 18:21 retrata algo dañado pero no destruido. Oseas 5:11 lo aplica a Efraín ''aplastado en el juicio''. La cualidad estativa lo distingue del evento activo de aplastar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137010, 'spa', 'Voz pasiva o media (Nifal/Qal intransitivo) que expresa que el sujeto es quebrad', 'Voz pasiva o media (Nifal/Qal intransitivo) que expresa que el sujeto es quebrado o destrozado. Eclesiastés 12:6 lo usa dos veces en su sobrecogedora alegoría de la muerte: el cuenco de oro ''se quiebra'' y el cántaro ''se hace pedazos''. Ezequiel 29:7 retrata a Egipto como un bastón de caña que se astilló al ser agarrado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137011, 'spa', 'Forma intensiva Piel que transmite un aplastamiento deliberado y completo', 'Forma intensiva Piel que transmite un aplastamiento deliberado y completo. Jueces 10:8 describe a los amonitas que ''aplastaron y oprimieron'' a Israel durante dieciocho años. El Salmo 74:14 celebra a Dios aplastando las cabezas de Leviatán. El Piel intensifica la violencia — destrucción sistemática, no incidental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137016, 'spa', 'Participio activo usado sustantivamente para designar a ''los que aplastan'' — los', 'Participio activo usado sustantivamente para designar a ''los que aplastan'' — los opresores como clase social. Amós 4:1 se dirige a las mujeres acaudaladas de Samaria como ''las que aplastan a los menesterosos''. La forma participial convierte una acción violenta en una identidad social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137018, 'spa', 'Forma recíproca Hitpael que describe una lucha o forcejeo mutuo', 'Forma recíproca Hitpael que describe una lucha o forcejeo mutuo. Génesis 25:22 narra cómo los gemelos ''se golpeaban'' dentro del vientre de Rebeca, provocando su angustiosa consulta al SEÑOR. La morfología recíproca es clave: no una parte aplastando a otra, sino dos seres presionándose mutuamente — un conflicto prenatal que presagia una vida entera de rivalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137021, 'spa', 'Participio pasivo usado sustantivamente para designar a ''los oprimidos'' como cat', 'Participio pasivo usado sustantivamente para designar a ''los oprimidos'' como categoría social. Isaías 58:6 define el verdadero ayuno como ''dejar libres a los oprimidos''. El participio cruza de adjetivo a sustantivo, nombrando a una clase definida por la violencia ejercida contra ella.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137024, 'spa', 'vacas demacradas', 'Las tres ocurrencias modifican el plural femenino ''vacas'' (פָּרוֹת) en la narrativa del sueño de Faraón. La evidencia multilingüe muestra términos cognados a través del español ''flacas'' (lean), mientras el alemán usa ''mageren'' (gaunt). La palabra aparece en paralelo con דַּקּוֹת (thin) en los versículos 3-4, creando un doblete que intensifica la imagen de flacura severa representando siete años de hambre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137025, 'spa', 'solo, ciertamente (restrictivo)', 'Adverbio restrictivo o aseverativo que significa ''solo,'' ''solamente,'' ''nada más que,'' o con fuerza enfática ''ciertamente,'' ''sin duda.'' Limita o intensifica la cláusula que modifica. Génesis 6:5 lo emplea con efecto devastador: toda inclinación del pensamiento humano era «solo mal continuamente.» Amós 3:2 lo usa para la elección divina exclusiva. La convergencia interlingüística es casi total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137030, 'spa', 'excepto (exceptivo)', 'Uso exceptivo poco frecuente que significa ''excepto'' o ''salvo que,'' introduciendo una excepción a una afirmación precedente. Atestiguado en 2 Re 17:18, donde tras la deportación de las tribus del norte, «no quedó sino solo la tribu de Judá.» Las traducciones árabes usan إِلَّا (''excepto'') y las francesas sauf en lugar del habitual seulement, proporcionando clara evidencia multilingüe de un sentido diferenciado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137034, 'spa', 'escupitajo despreciativo', 'Dos pasajes (Job 30:10, Isaías 50:6) involucran escupir con desprecio, mientras Job 7:19 usa tragar saliva como metáfora temporal. El español distingue entre ''saliva'' (la sustancia) y ''escupir'' (el acto), mientras las traducciones luchan con el modismo temporal en 7:19. El pasaje de Isaías es parte del Cántico del Siervo describiendo humillación, haciendo la referencia al escupir particularmente conmovedora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137036, 'spa', 'Podredumbre figurada', 'Podredumbre o descomposición figurada para la corrupción interna lenta. Las cinco apariciones son metafóricas: Dios actúa como carcoma consumiendo a Judá (Os 5:12, emparejado con ''polilla''), y la envidia es ''podredumbre de huesos'' (Prov 12:4; 14:30). En Habacuc 3:16 los huesos del profeta se pudren de pavor. ''Podredumbre'' y ''carcoma'' captan el doble matiz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137038, 'spa', 'Saltar, brincar (Qal)', 'Salto o brinco sencillo en la conjugación Qal. Los montes personificados saltan como carneros durante el Éxodo (Sal 114:4, 6) y el proverbial ''tiempo de danzar'' que equilibra ''tiempo de enlutarse'' (Ecl 3:4). El español ''saltaron/para danzar'' y el francés ''bondir'' preservan el sentido de movimiento más ligero y básico, distinto de la intensidad del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137039, 'spa', 'Hacer saltar (Hifil)', 'Salto causativo en la conjugación Hifil: hacer que algo brinque. Se usa una sola vez en Sal 29:6, donde la voz tronante del SEÑOR hace saltar al Líbano y al Sirión como un becerro salvaje. El español ''y los hace saltar'' captura la fuerza causativa: es Dios quien obliga incluso a los montes a brincar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137042, 'spa', 'Danzar, brincar (Piel)', 'Danza o salto vigoroso en la conjugación intensiva Piel. La danza extática de David ante el arca (1 Cr 15:29), niños retozando con alegría (Job 21:11), cabras monteses brincando entre ruinas (Is 13:21), langostas saltando sobre montes (Jl 2:5) y carros retumbando (Nah 3:2). El español ''danzan/saltan'' refleja la intensidad enérgica del Piel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137047, 'spa', 'Sien de la cabeza', 'La sien, zona delgada y vulnerable a un lado del cráneo. En Jueces 4:21-22 y 5:26, Jael atraviesa la sien de Sísara con una estaca, subrayando vulnerabilidad letal. En Cantar de los Cantares 4:3 y 6:7, la sien de la amada resplandece como granada tras su velo, evocando belleza. El español ''sien'' y el francés ''tempe'' designan esta zona anatómica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137049, 'spa', 'Mezclar, preparar ungüentos', 'Mezclar o preparar ungüentos sagrados y especias aromáticas, y por extensión, el profesional que desempeña este oficio. En Éxodo 30:25, 33, 35 y 37:29, el verbo describe la preparación del aceite santo de unción y del incienso según prescripción divina; 1 Crónicas 9:30 emplea el participio plural para los especialistas levíticos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137060, 'spa', 'La vasta bóveda o cúpula del cielo, concebida como una superficie batida a marti', 'La vasta bóveda o cúpula del cielo, concebida como una superficie batida a martillo que separa las aguas superiores de las inferiores. Creada en el Segundo Día (Gn 1:6-8) y portadora del sol, la luna y las estrellas (Gn 1:14-17). En las visiones de Ezequiel aparece como una plataforma cristalina sobre los querubines que sostiene el trono divino (Ez 1:22-26; 10:1). Los Salmos la celebran como proclamadora de la obra de las manos de Dios (Sal 19:1), y Daniel 12:3 compara a los sabios con el resplandor del firmamento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137066, 'spa', 'Oblea, hojuela sin levadura', 'Oblea fina sin levadura preparada para ceremonias sacrificiales y de consagración. Las ocho ocurrencias pertenecen a legislación ritual sacerdotal: consagración de Aarón (Éx 29:2, 23; Lv 8:26), ofrenda de cereal (Lv 2:4; 7:12), dedicación nazarea (Nm 6:15, 19) y servicio del templo (1 Cr 23:29). Siempre se empareja con matstsot (pan sin levadura), confirmando su carácter de pan ritual específico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137071, 'spa', 'Bordador', 'Participio Qal usado como sustantivo: un bordador o abigarrador, el artesano que labra diseños decorativos con hilos de colores. Aparece exclusivamente en los relatos de la construcción del Tabernáculo (Éxodo 26–39), donde el oficio del bordador se distingue del tejedor y del diseñador. El español ''bordador'' refleja este vocabulario textil especializado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137073, 'spa', 'Tejido, entretejido', 'Pasivo Pual: ser intrincadamente tejido o hábilmente labrado. En el Salmo 139:15, el salmista se maravilla de haber sido ''entretejido'' en lo profundo de la tierra (metáfora del vientre materno), empleando la voz pasiva de este verbo de bordado para describir la artesanía creadora de Dios. El español ''fui entretejido'' captura la asombrosa metáfora: la creación divina como arte textil magistral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137074, 'spa', 'Requem (nombre propio)', 'Nombre propio hebreo aplicado a múltiples individuos y una localidad. Como nombre personal designa: (a) un rey madianita muerto por Israel en la guerra de Números 31:8, mencionado también en Josué 13:21; (b) un hijo de Hebrón en la genealogía calebita de 1 Crónicas 2:43-44; y (c) un galaadita en 1 Crónicas 7:16. Como topónimo se refiere a una ciudad benjaminita en Josué 18:27.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137076, 'spa', 'Bordado, labor bordada', 'Bordado o labor abigarrada de aguja como sustantivo colectivo o abstracto: el oficio, el producto o el material del arte textil decorativo. Se usa para las vestiduras que Dios otorgó a la Jerusalén personificada (Ez 16:10, 13, 18), para los tejidos comerciados por Tiro (Ez 27:7, 16, 24), para el plumaje multicolor del águila (Ez 17:3) y para la ''piedra abigarrada'' contribuida para el templo (1 Cr 29:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137077, 'spa', 'Prendas bordadas', 'Prendas o paños bordados concretos: artículos específicos de tela ricamente decorada, no el oficio en abstracto. El cántico de Débora celebra el botín con רִקְמָתַיִם, ''un par de paños bordados,'' para el cuello del saqueador (Jue 5:30, usado dos veces en el versículo). En el Salmo 45:14, la novia real es conducida con ''vestidos bordados.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137086, 'spa', 'Extender (cielos/tierra)', 'Extender o desplegar algo vasto, especialmente los cielos o la tierra, con Dios como agente de la creación cósmica. En Job 37:18, Elihú pregunta: ''¿Puedes tú, con él, extender los cielos, firmes como un espejo fundido?'' Isaías lo emplea dos veces (42:5; 44:24) para celebrar a Dios como quien extendió la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137087, 'spa', 'Patear, pisotear', 'Patear con el pie o pisotear, expresando desprecio violento o conquista militar. David declara que aplastó a sus enemigos como polvo (2 S 22:43), mientras que a Ezequiel se le ordena patear con el pie y aplaudir como gesto de desprecio afligido por las abominaciones de Israel (Ez 6:11). Los amonitas patean con gozo malicioso ante la caída de Jerusalén (Ez 25:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137088, 'spa', 'Batir en láminas', 'Batir o martillar metal en láminas o planchas delgadas, un sentido técnico de metalurgia que aparece en las formas Piel y Pual. En Éxodo 39:3, los artesanos baten el oro en láminas finas y las cortan en hilos para el efod sacerdotal, y en Números 16:39 los incensarios de los rebeldes de Coré son batidos para revestir el altar. Jeremías 10:9 describe la plata batida importada de Tarsis.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137094, 'spa', 'Recubrir con metal', 'Recubrir o revestir un objeto extendiendo metal batido sobre él, una extensión especializada del sentido metalúrgico. Isaías 40:19 describe al artesano que funde un ídolo y luego lo recubre con oro. La forma Piel aquí enfatiza la completitud de la acción de revestimiento, pasando del acto de batir en láminas (sentido 3) a la aplicación de esas láminas como chapado decorativo sobre un objeto terminado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137101, 'spa', 'Ser inscrito, registrado', 'Sentido pasivo: ser inscrito o registrado por escrito, específicamente de un texto que aparece en un documento o superficie sin que el agente sea el sujeto gramatical. En Dn 5:24 la mano es enviada y «esta escritura fue inscrita» (reshim), y en Dn 5:25 las palabras — MENE MENE TEKEL UFARSIN — se identifican como la inscripción que «fue escrita».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137102, 'spa', 'Firmar, escribir (activo)', 'Sentido activo: firmar o redactar un documento oficial, específicamente un decreto o edicto real. Las cinco ocurrencias se concentran en Daniel 6, donde el rey Darío es persuadido a firmar un decreto que prohíbe orar a cualquier dios u hombre excepto a él mismo. El verbo abarca tanto el acto físico de escribir como la autenticación formal de la firma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137106, 'spa', 'Qal', 'Qal: ser malvado u obrar con corrupcion moral, describiendo el estado pecaminoso del sujeto. David protesta en 2 Samuel 22:22 que no se ha ''apartado impiamente'' de Dios; las confesiones comunitarias en 1 Reyes 8:47 y Daniel 9:15 usan esta forma para el reconocimiento nacional del pecado. Job 9:29 y 10:7 emplean esta forma en la angustiada protesta de Job ante Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137107, 'spa', 'Hifil declarativo', 'Hifil declarativo: condenar o declarar culpable en un contexto judicial. Deuteronomio 25:1 establece el paradigma: los jueces ''justificaran al justo y condenaran al malvado.'' En Exodo 22:9, aquel a quien los jueces ''condenen'' debe pagar el doble. Proverbios 17:15 advierte que quien justifica al malvado y condena al justo son ambos abominacion al SENOR.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137110, 'spa', 'Uso aislado en 1 Samuel 24', 'Uso aislado en 1 Samuel 24:13 donde la forma aparece en el dicho proverbial ''de los malvados sale la maldad.'' La evidencia multilingue trata esto consistentemente como uso sustantivado: ''el malvado'' como categoria de persona. David cita este proverbio antiguo ante Saul, distanciandose de aquellos cuya naturaleza produce iniquidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137117, 'spa', 'Hifil elativo o intransitivo', 'Hifil elativo o intransitivo: obrar con maldad de manera deliberada e intensificada. Se distingue del sentido 2 por el Hifil que senala mayor agencia. Nehemias 9:33 confiesa ''hemos obrado perversamente'' usando esta forma intensificada; 2 Cronicas 20:35 describe a Ocozias que ''obro impiamente'' en alianza con reyes malvados; Daniel 9:5 acumula sinonimos de pecado con esta forma como climax.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137141, 'spa', 'Maldad o culpa moral como cualidad del carácter y la conducta, en oposición fund', 'Maldad o culpa moral como cualidad del carácter y la conducta, en oposición fundamental al orden justo de Dios. Funciona como antítesis de tsedaqah en la literatura sapiencial (Prov 10:2; Ecl 3:16). En los profetas adquiere forma social concreta: el ''puño de maldad'' (Isa 58:4), las ''ataduras de maldad'' (Isa 58:6) y los ''tesoros de maldad'' (Miq 6:10). El antiguo proverbio de 1 Sam 24:13 la trata como fuerza que se autopropaga.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137155, 'spa', 'persona impía, malvada', 'Persona moralmente impía o malvada, usado sustantivamente como el opuesto arquetípico del justo (צַדִּיק). Con 259 apariciones, es el sentido dominante en la literatura sapiencial (Pr 10:3, «Jehová no dejará padecer hambre al justo, mas rechazará la satisfacción de los impíos»), Salmos (Sal 1:1, 6), juicio profético (Is 13:11) y narrativa (Gn 18:23, la intercesión de Abraham).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137170, 'spa', 'culpable, reo', 'Quien es legal o forense culpable — merecedor de castigo judicial. Cuatro apariciones en contextos claramente jurídicos: Nm 35:31 (''homicida que es culpable de muerte''), Dt 25:1-2 (el juez ''condenará al culpable'') y Sal 109:7 (''salga declarado culpable''). Aquí רָשָׁע funciona no como descripción de carácter moral sino como veredicto judicial. La evidencia multilingüe confirma la diferenciación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137195, 'spa', 'Maldad, impiedad', 'Maldad, impiedad. Perversidad moral abstracta como condición o cualidad, que frecuentemente caracteriza a grupos, naciones o fuerzas personificadas: la maldad de las naciones (Dt 9:4-5), la maldad que devora como fuego (Is 9:18), y la impactante personificación en Zacarías 5:8 donde el ángel declara ''esto es la maldad'' sobre una mujer dentro de un efa. El español oscila entre ''maldad'' y ''impiedad'' para este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137196, 'spa', 'Culpa, maldad culpable', 'Culpa, maldad culpable. Maldad personal y culpable atribuida a un individuo específico, enfatizando la responsabilidad moral y la posibilidad de arrepentimiento. Deuteronomio 25:2 la usa para referirse a un culpable merecedor de azotes, mientras que Ezequiel la empareja repetidamente con el apartarse: ''cuando el impío se aparta de su maldad'' (Ez 18:27; 33:12, 19). Los sufijos posesivos consistentes en hebreo subrayan esta dimensión personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137205, 'spa', 'Llama, brasa, fuego', 'Llama, brasa ardiente o chispa — fuego visible en su forma elemental. Cantares 8:6 acumula resheph sobre resheph para describir la llama abrasadora del amor. Job 5:7 utiliza «hijos de resheph» (chispas) como proverbio sobre la inevitabilidad del sufrimiento. Las traducciones «brasas» y «chispa» captan con precisión la imaginería concreta del fuego. (Cnt 8:6; Job 5:7)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137207, 'spa', 'Plaga, pestilencia, fiebre', 'Plaga, pestilencia o fiebre — fuerza destructiva enviada por Dios, eco de la deidad cananea de la plaga, Resheph. En Deuteronomio 32:24 aparece junto a la destrucción amarga; en Habacuc 3:5 la pestilencia y resheph marchan ante Dios en juicio teofánico. Las traducciones oscilan entre enfermedad y devastación sobrenatural. (Dt 32:24; Hab 3:5)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137208, 'spa', 'Rayo, flecha de fuego', 'Rayo o flecha de fuego — proyectil divino usado como arma. El Salmo 78:48 lo empareja con el granizo como juicio sobre Egipto, y el Salmo 76:3 describe a Dios quebrando los «resheph del arco» — dardos llameantes de guerra. Las traducciones «rayos» y «relámpagos» subrayan su cualidad de proyectil. (Sal 76:3; 78:48)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137214, 'spa', 'Red utilizada para atrapar aves, peces o animales, ya sea literal o, más comúnme', 'Red utilizada para atrapar aves, peces o animales, ya sea literal o, más comúnmente, en sentido figurado. El uso figurado predomina: los malvados atrapan al inocente (Sal 9:15; 10:9; 25:15), y Dios extiende su red en juicio sobre Egipto (Ez 32:3) e Israel infiel (Os 7:12). Proverbios 1:17 ofrece el único caso puramente literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137217, 'spa', 'Enrejado, retícula o rejilla — específicamente la rejilla de bronce del altar de', 'Enrejado, retícula o rejilla — específicamente la rejilla de bronce del altar del tabernáculo descrita en Éxodo 27:4–5 y 38:4. Este sentido arquitectónico designa una estructura metálica rígida de trama abierta, distinta de un dispositivo flexible para atrapar. La traducción uniforme como ''enrejado'' o ''rejilla'' distingue este término técnico cultual del uso metafórico de la red.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137226, 'spa', 'cadenas ornamentales o restrictivas', 'Las tres ocurrencias se dividen entre cadenas decorativas del templo (1 Reyes 6:21, apareciendo dos veces en el versículo) y cadenas de cautiverio (Ezequiel 7:23). Las traducciones españolas ''cadenas'' y francesas ''chaîne'' representan el término directamente. El pasaje de Ezequiel con su mandato de ''hacer la cadena'' es textualmente incierto, con algunos eruditos proponiendo enmiendas, sugiriendo que el original pudo haber previsto cadenas para el exilio inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137227, 'spa', 'hervir literal y figurado', 'Los tres usos se dividen entre el hervir literal (la olla de Ezequiel) y el bullir figurativo (las emociones de Job y el poder de Leviatán). El español ''hervir'' y el francés ''bouillir'' aparecen consistentemente. La descripción de Job 30:27 de entrañas hirviendo ''sin reposo'' transmite poderosamente turbulencia interior, mientras que el pasaje de Leviatán usa el hervir para ilustrar la temible capacidad de la criatura de agitar las profundidades del océano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137230, 'spa', 'Arbusto desértico', 'Designa un arbusto de retama del desierto. En 1 Reyes 19:4-5, Elías se sienta bajo «una retama» (רֹתֶם אֶחָד) deseando morir; el escuálido arbusto acentúa su desolación. Job 30:4 menciona a indigentes comiendo «raíces de retama» (שֹׁרֶשׁ רְתָמִים) para sobrevivir, indicando pobreza extrema. Salmo 120:4 habla de «brasas de retama» (גַּחֲלֵי רְתָמִים), que arden con especial intensidad y duración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137235, 'spa', 'Sacar o extraer agua de un pozo, manantial o cisterna, incluyendo formas partici', 'Sacar o extraer agua de un pozo, manantial o cisterna, incluyendo formas participiales que designan a la persona que realiza esta tarea. El uso literal abarca la vida cotidiana (Gn 24:11; 1 Sam 9:11; Rut 2:9) y contextos rituales (1 Sam 7:6). Isaías 12:3 lo extiende metafóricamente a sacar salvación como se saca agua, un notable giro figurado preservado en todas las principales traducciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137247, 'spa', 'Rugir como un león o una bestia feroz, usado literalmente de depredadores y figu', 'Rugir como un león o una bestia feroz, usado literalmente de depredadores y figuradamente de Dios, enemigos o gobernantes opresivos que rugen en poder, amenaza o juicio. El león joven ruge contra Sansón (Jue 14:5), los leones rugen buscando presa (Sal 104:21), los enemigos rugen en el santuario (Sal 74:4) y Dios mismo ruge desde Sion (Jer 25:30). Oseas 11:10 presenta la impactante imagen de Dios rugiendo como león para llamar a sus hijos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137261, 'spa', 'Gemir o clamar en profunda angustia personal, atestiguado en el Salmo 38', 'Gemir o clamar en profunda angustia personal, atestiguado en el Salmo 38:8 donde el salmista describe su gemido por la turbación interior. El mismo sonido visceral y gutural usado para el rugido de un león se redirige para expresar un dolor emocional abrumador — una conmovedora extensión semántica que muestra cómo la ferocidad animal y el sufrimiento humano comparten la misma voz primordial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137262, 'spa', 'Rugido de leones', 'El rugido de un león, empleado tanto en sentido literal como en poderosa metáfora de fuerza agresiva y depredadora. Isaías 5:29 compara el rugido de naciones invasoras al gruñido leonino. Job 4:10 lo usa figuradamente para los impíos cuyo rugido Dios acalla. Ezequiel 19:7 describe a un joven león cuyo rugido devasta ciudades.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137266, 'spa', 'Gemido de aflicción', 'Gemido o clamor angustioso de un ser humano en profundo sufrimiento, un sonido que comparte la intensidad del rugido leonino pero redirigido hacia dentro por el dolor. En el Salmo 22:1, David clama con «las palabras de mi gemido» (דִּבְרֵי שַׁאֲגָתִי), el salmo que Jesús citó desde la cruz. El Salmo 32:3 habla de gemir todo el día.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137269, 'spa', 'Rugir, bramar', 'Rugir, causar estruendo — usado de naciones que avanzan como aguas atronadoras. Isaías 17:12-13 describe pueblos que ''braman como el bramar de muchas aguas'', símil del aterrador avance de ejércitos enemigos. El verbo paralelo ''hamah'' (estar en tumulto) refuerza el caos auditivo. La imagen transmite la cualidad bestial y abrumadora del sonido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137270, 'spa', 'Ser devastado', 'Derrumbarse en ruinas, ser devastado (Qal y Nifal). En Isaías 6:11 el profeta pregunta ''¿Hasta cuándo, Señor?'' y se le responde: hasta que las ciudades ''sean devastadas'' sin habitante y la tierra quede completamente desolada. El Nifal intensifica la devastación — no meramente dañado sino reducido a ruina inhabitable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137271, 'spa', 'Hacer desolado', 'Hacer desolado, causar devastación (Hifil causativo). En los pasajes paralelos de 2 Reyes 19:25 e Isaías 37:26, Dios declara que planeó desde antiguo que el asirio ''asolara ciudades fortificadas convirtiéndolas en montones ruinosos''. La raíz causativa clarifica que el agente destructor actúa bajo la soberanía divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137276, 'spa', 'El inframundo o morada de los muertos', 'El inframundo o morada de los muertos. Con 65 apariciones, el Seol es el gran igualador de la antropología hebrea: el lugar al que descienden todos los muertos. Las traducciones lo rinden sistemáticamente con vocabulario específico del inframundo — «Seol», séjour-des-morts (''morada de los muertos''), Totenreich (''reino de los muertos'') — confirmando su identidad como ubicación cosmológica y no mera metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137295, 'spa', 'Un imperativo verbal que significa «pide» o «solicita», probablemente un solapam', 'Un imperativo verbal que significa «pide» o «solicita», probablemente un solapamiento homográfico con el verbo שָׁאַל. En Is 7:11 se ordena a Acaz que pida (שְׁאֹל) una señal del SEÑOR. El español «la petición» y el inglés «asking» tratan esto como el verbo en vez del sustantivo, aunque la ambigüedad no siempre fue reconocida en las tradiciones de traducción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137296, 'spa', 'Saúl (nombre propio)', 'Nombre propio masculino derivado de la raíz שָׁאַל (''pedir, solicitar''), aplicado principalmente al primer rey de Israel, hijo de Cis de Benjamín (1 S 9:2), cuyas más de 360 apariciones dominan el corpus. También lo llevan un rey edomita (Gn 36:37), un ancestro del clan de Simeón (Gn 46:10; Éx 6:15) y un levita (1 Cr 6:9). El vínculo etimológico con ''pedir'' resuena en la narrativa de Israel pidiendo un rey.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137312, 'spa', 'El rugido, tumulto o estruendo de multitudes, ejércitos o aguas — un sonido fuer', 'El rugido, tumulto o estruendo de multitudes, ejércitos o aguas — un sonido fuerte, abrumador y frecuentemente amenazante. Isaías 17:12-13 lo usa dos veces para el fragor atronador de naciones hostiles comparadas con mares rugientes. El Salmo 65:7 alaba a Dios que acalla el bramido de las olas. Amós 2:2 y Oseas 10:14 lo aplican al estruendo de la batalla, y Jeremías 48:45 llama a los guerreros ''hijos de tumulto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137316, 'spa', 'Destrucción rugiente o desolación — una extensión contextual de la imagen de tum', 'Destrucción rugiente o desolación — una extensión contextual de la imagen de tumulto hacia la ruina resultante. En el Salmo 40:2, el salmista es sacado de un ''pozo de destrucción'' (o ''pozo de estruendo tumultuoso''), donde el caos auditivo del sentido 1 se fusiona con la devastación física que produce. El ruido se transforma en los escombros que el trueno deja tras de sí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137321, 'spa', 'desprecio profundo', 'Las tres ocurrencias están en Ezequiel 25 y 36, describiendo las actitudes despectivas de Amón (25:6), Edom (25:15) y otras naciones (36:5) hacia Israel. Las traducciones españolas ''desprecio'' y francesas capturan la noción de menosprecio o desdén. El término aparece consistentemente en la frase ''con desprecio de alma'', sugiriendo malicia internalizada en lugar de insulto momentáneo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137322, 'spa', 'los que desprecian habitualmente', 'Las tres ocurrencias describen a los vecinos de Israel que la desprecian: mujeres filisteas (16:57) y pueblos circundantes (28:24, 26). El español usa ''los/las que desprecian'', capturando el sentido participial. Los contextos prometen alivio de tales vecinos despectivos, parte de los oráculos de restauración de Ezequiel. La restricción del término a Ezequiel sugiere que puede ser una forma dialectal o tardía.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137324, 'spa', 'preguntar, inquirir', 'Hacer una pregunta o una indagación, buscando información de otra persona o de Dios. El árabe sa''ala y el coreano mul-eotda marcan consistentemente este como el registro de búsqueda de información. Es el sentido dominante (96x), abarcando desde preguntas interpersonales sencillas (Gn 26:7 «los hombres del lugar preguntaron por su esposa») hasta consultas divinas formales por sacerdote o profeta (Jue 1:1; 1 S 10:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137326, 'spa', 'pedir, solicitar, demandar', 'Pedir, solicitar o demandar algo de alguien, buscando obtener bienes, favores o resultados en vez de información. El árabe talaba (solicitar) y el coreano guhaetda (obtener) distinguen este sentido de la mera indagación. Abarca la declaración de Moisés sobre lo que Dios «pide de» Israel (Dt 10:12), la hija de Caleb pidiendo manantiales (Jos 15:18) y los ancianos exigiendo un rey (1 S 8:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137364, 'spa', 'tomar prestado', 'Tomar prestado, recibir algo en préstamo de otro. El árabe musta''ar (prestado) y el coreano billin (prestado) marcan la transacción económica. Poco frecuente (3x), aparece en la casuística de Éx 22:14 sobre la responsabilidad por un animal prestado, la declaración de Ana de que Samuel fue «prestado a Jehová» (1 S 1:28 — juego de palabras deliberado) y la cabeza de hacha que «era prestada» (2 R 6:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137378, 'spa', 'prestar, conceder', 'Hifil causativo: prestar, conceder en préstamo a otro. El árabe a''ara (prestar) y el coreano billyeojuda (prestar) confirman el giro causativo de recibir a conceder. Aparece solo dos veces: los israelitas recibiendo oro y plata de los egipcios al salir de Egipto (Éx 12:36), y el voto de Ana de que ha «prestado» a Samuel a Jehová (1 S 1:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137385, 'spa', 'pedir permiso', 'Pedir licencia o permiso para partir. Una extensión pragmática especializada del sentido de petición, que aparece en Neh 13:6 donde Nehemías pide permiso al rey para regresar a Jerusalén. El español pedí permiso confirma el registro diplomático-cortesano. La construcción es idiomática: שָׁאַל funciona como solicitud de autorización formal más que como simple pregunta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137386, 'spa', 'mendigar, suplicar', 'Mendigar, suplicar como persona indigente. Un cambio de registro hacia la súplica abyecta, que aparece en el Salmo imprecatorio 109:10 (''que sus hijos mendiguen''). El español mendiguen capta la degradación social implícita. Donde el sentido 2 cubre la petición digna, este sentido conlleva la connotación de un pedir desesperado y repetido nacido de la pobreza — el suelo semántico de un verbo cuyo techo es la petición real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137436, 'spa', 'Preguntar, inquirir', 'Hacer una pregunta o realizar una indagación buscando información o respuesta de alguien. Incluye el perfectivo ''preguntamos'' (Esd 5:9-10), el participio ''el que pregunta'' (Dan 2:11, 27) y el pretérito simple ''preguntó'' (Dan 2:10). En cada caso el contexto es de interrogación o consulta: Tatnai cuestionando a los constructores, Nabucodonosor exigiendo interpretación a sus sabios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137438, 'spa', 'Solicitar, exigir', 'Hacer una solicitud o exigencia a alguien, pidiendo que se conceda o realice algo en lugar de simplemente buscar información. El único caso es Esdras 7:21, donde el rey Artajerjes decreta que todo lo que el sacerdote Esdras ''os pida'' a los tesoreros del otro lado del río debe cumplirse. Implica una petición directiva con una estructura de autoridad implícita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137442, 'spa', 'Petición, solicitud', 'Petición, solicitud. Una solicitud formal dirigida a una persona de autoridad. Gedeón pide a los israelitas pendientes de oro (Jue 8:24); Betsabé presenta ''una pequeña petición'' a Salomón (1 R 2:20); Ester es invitada repetidamente a expresar su petición ante el rey (Est 5:6; 7:2). La petición profundamente personal de Ana a Dios (1 Sam 1:27) muestra que el término abarca tanto el ámbito real como el divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137449, 'spa', 'Préstamo, cosa prestada', 'Préstamo, cosa prestada. Un matiz especializado que significa ''lo prestado'' o ''préstamo'': el objeto concreto o la bendición concedida en respuesta a una petición. En 1 Sam 2:20, Elí bendice a Elcana pidiendo que el SEÑOR le retribuya por ''el préstamo'' que Ana dedicó al SEÑOR, refiriéndose a Samuel mismo como el don otorgado y ahora devuelto al servicio de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137450, 'spa', 'Salatiel (nombre propio)', 'Nombre propio teofórico que significa ''le pedí a Dios'', portado por el padre de Zorobabel. Según 1 Crónicas 3:17 fue el primogénito del rey exiliado Joaquín. Su importancia radica en anclar la línea davídica postexílica: cada aparición lo vincula con Zorobabel como líder del retorno (Esd 3:2, 8; Neh 12:1; Hag 1:1; 2:23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137453, 'spa', 'padre de Zorobabel', 'Las tres ocurrencias están en Hageo, identificando al padre de Zorobabel en las exhortaciones del profeta para reconstruir el templo. Las transliteraciones españolas ''Sealtiel'' y alemanas ''Schealtiel'' muestran variaciones menores. La fórmula genealógica consistente enfatiza descendencia davídica legítima, crucial para establecer la autoridad de Zorobabel. Hageo 1:12-14 muestra al pueblo obedeciendo la voz de Dios a través del profeta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137455, 'spa', 'Tranquilidad segura', 'Estar tranquilo, reposar seguro, habitar sin perturbación ante calamidad o amenaza. Jeremías lo emplea para la restauración prometida de Israel, en quietud sin que nadie los atemorice (Jer 30:10; 46:27), y con ironía para la falsa seguridad de Moab (Jer 48:11). Proverbios 1:33 lo asocia con la libertad del temor al mal; Job 3:18, con el reposo de la tumba.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137456, 'spa', 'Complaciente, despreocupado', 'Complacencia, falsa seguridad o despreocupación en sentido peyorativo, reprendida por los profetas como peligro espiritual. Amós 6:1 (''¡Ay de los que están tranquilos en Sion!''), Is 32:9, 11 (''mujeres complacientes''), Sal 123:4 (el desprecio de los complacientes) y Zac 1:15 (naciones ''tranquilas'' mientras Israel sufría) portan esta carga condenatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137457, 'spa', 'Arrogancia insolente', 'Arrogancia o autosuficiencia insolente llevada al extremo, describiendo un orgullo agresivo ante Dios. Atestiguada en los pasajes paralelos de 2 R 19:28 e Is 37:29, donde Dios confronta a Senaquerib: ''tu arrogancia ha subido a mis oídos''. El español ''arrogancia'' es inequívoco. BDB señala la variante textual ''tumulto'', pero la lectura masorética preserva el vínculo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137458, 'spa', 'Tranquilo, seguro', 'Genuina tranquilidad, seguridad y paz imperturbable, condición positiva de reposo bendito. Isaías 32:18 promete a su pueblo ''lugares de descanso seguros'' y 33:20 celebra a Jerusalén como ''morada tranquila''. Job 12:5 describe a quien está ''en paz'' en contraste con el que sufre, aunque roza el sentido peyorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137466, 'spa', 'Jadear, resollar', 'Jadeo o respiración agitada en sentido físico. En Isaías 42:14 Dios rompe su largo silencio con la imagen de una mujer en parto: «resollaré y jadearé a la vez». Jeremías 2:24 describe una asna montés olfateando el viento, y Jeremías 14:6 muestra asnos monteses jadeando en alturas desnudas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137468, 'spa', 'Anhelar, desear', 'Anhelo o deseo intenso en sentido figurado: el jadeo físico transferido al ámbito emocional. Job 7:2 compara al hombre sufriente con un siervo que «anhela» la sombra, y Job 36:20 advierte contra «anhelar la noche». El vocabulario pasa de lo respiratorio a lo emocional, confirmando la transferencia metafórica del cuerpo al alma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137472, 'spa', 'Apresurarse, correr', 'Apresurarse o correr con urgencia, extensión del jadeo al correr. Eclesiastés 1:5 lo aplica al sol: «se apresura (שׁוֹאֵף) al lugar donde sale», retratando al sol como un corredor sin aliento que completa su circuito diario. El sentido se desplaza del ámbito físico-respiratorio al temporal, tendiendo un puente entre ambas dimensiones de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137475, 'spa', 'Tragar, devorar', 'Tragar o devorar, el acto de ser engullido, usado con el infinitivo absoluto Qal para énfasis retórico. En Ezequiel 36:3, las naciones que rodeaban a Israel ''tragaron'' (שָׁאֹף) la tierra desde todos los lados. Esta metáfora de ingestión es distinta de la violencia del pisoteo del sentido 1 y exclusiva de Ezequiel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137476, 'spa', 'Pisotear, aplastar', 'Pisotear, aplastar o perseguir con intención hostil y agresiva. El salmista clama que sus enemigos ''me pisotean'' todo el día (Sal 56:1-2) y que su adversario envía ''al que me aplasta'' (Sal 57:3). Amós condena a los ricos que ''pisotean'' a los pobres y necesitados (Am 2:7; 8:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137480, 'spa', 'Levadura', 'Levadura, la masa fermentada usada para leudar el pan. Cada aparición es cultual y prohibitiva: debe purgarse de los hogares durante la semana de Pascua (Éx 12:15, 19; 13:7; Dt 16:4) y está vedada en las ofrendas de cereal (Lv 2:11). Español ''levadura,'' francés ''levain'' y alemán ''Sauerteig'' confirman un único referente concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137481, 'spa', 'quedar, sobrar (Nifal)', 'Nifal intransitivo: quedar, sobrar, sobrevivir después de que otros han perecido, partido o sido consumidos. El sentido nuclear con 53 apariciones, abarcando literatura narrativa y profética por igual. Tras el Diluvio, solo Noé «quedó» (Gn 7:23); el grano de José es todo lo que «queda» en Egipto (Gn 47:18). El español quedaron capta el resultado estativo: lo que aún permanece en pie después de la catástrofe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137482, 'spa', 'los restantes, remanente', 'Participio Nifal usado sustantivamente: los que quedan, el remanente, los supervivientes — un grupo de 42 apariciones que se convirtió en una de las construcciones más cargadas teológicamente. En Gn 32:8 Jacob divide su campamento para que «el grupo restante» pueda escapar; en Isaías y los profetas, «el remanente» designa a los preservados a través del juicio divino (cf. el derivado שְׁאֵרִית).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137483, 'spa', 'dejar restante, perdonar (Hifil)', 'Hifil causativo: dejar restante, dejar sobrante, perdonar la vida, permitir sobrevivir. Con 38 apariciones es la contrapartida agentiva de los sentidos 1-2: alguien causa deliberadamente que otros permanezcan vivos o que algo quede. En Nm 21:35 Israel «no dejó sobreviviente»; en Dt 2:34 «no dejaron a nadie.» El español dejaron confirma el marco causativo activo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137557, 'spa', 'Lo que permanece después de que una parte ha sido removida, usado tanto para res', 'Lo que permanece después de que una parte ha sido removida, usado tanto para restos ordinarios (el resto de los actos de Salomón, 2 Cr 9:29; la plata sobrante, 2 Cr 24:14; el resto de la comunidad que regresó, Esd 3:8; 4:3; Neh 10:28; 11:1) como para el teológicamente potente ''remanente'' del juicio divino. Isaías concentra el peso teológico: Sear-jasub (''un remanente volverá,'' Isa 7:3), el bosque diezmado tan escaso que un niño podría contarlo (Isa 10:19), y la eliminación de ''nombre y remanente'' de Babilonia (Isa 14:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137561, 'spa', 'Resto, remanente', 'El remanente, lo que queda — término arameo administrativo y narrativo para la porción restante de un grupo, territorio o reino. En Esdras, designa a los pueblos asentados en Samaria (Esd 4:9-10), se dirige a ''el resto de sus compañeros'' en cartas persas (Esd 4:17; 7:18). En Daniel, describe lo que queda de reinos destruidos (Dn 7:7, 12, 19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137566, 'spa', 'Un pariente consanguíneo cercano — alguien que es ''de la misma carne'' — usado es', 'Un pariente consanguíneo cercano — alguien que es ''de la misma carne'' — usado especialmente en las regulaciones levíticas que rigen las uniones sexuales prohibidas y los derechos de duelo sacerdotal. Siete ocurrencias se concentran en Levítico 18, 20 y 21, donde la frase she''er avikha (''el pariente carnal de tu padre'', Lv 18:12-13) define los grados de parentesco dentro de los cuales el matrimonio está prohibido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137567, 'spa', 'La carne física o el cuerpo de una persona, designando la sustancia corporal que', 'La carne física o el cuerpo de una persona, designando la sustancia corporal que cubre los huesos y palpita con vida. El salmista declara que ''mi carne y mi corazón desfallecen, pero Dios es la fortaleza de mi corazón'' (Sal 73:26), y Dios provee carne a Israel en el desierto — ''carne como polvo, aves aladas como arena de los mares'' (Sal 78:27). Este sentido enfatiza la materialidad vulnerable del cuerpo humano.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137575, 'spa', 'Alimento o sustento debido a una persona dependiente, específicamente la provisi', 'Alimento o sustento debido a una persona dependiente, específicamente la provisión que un esposo debe garantizar a su esposa junto con vestimenta y derechos conyugales. Este sentido raro aparece solo una vez, en Éxodo 21:10, donde la ley estipula que si un hombre toma una segunda esposa, ''no disminuirá su alimento (she''arah), su vestimenta ni sus derechos maritales''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137582, 'spa', 'La porción sobreviviente de un pueblo o nación tras una calamidad', 'La porción sobreviviente de un pueblo o nación tras una calamidad. Este sentido teológicamente cargado representa casi todas las apariciones, presente en los profetas como motivo tanto de juicio como de esperanza. Las traducciones emplean uniformemente vocabulario de «remanente» — remanente, reste, Rest. José dice a sus hermanos que Dios lo envió delante para preservar un remanente en la tierra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137594, 'spa', 'La porción restante de cosas no personales o materiales', 'La porción restante de cosas no personales o materiales. En Is 44:17, un hombre quema parte de un tronco para cocinar y con la שְׁאֵרִית (''el resto'') talla un ídolo — una mordaz ironía. En Jer 15:9, la madre de siete expira y su «resto» (su fuerza vital restante o descendencia) es entregado a la espada. Se trata como «el resto de ello», una extensión material y no personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137601, 'spa', 'Hinchazón, lesión cutánea', 'Hinchazón, lesión cutánea. Una hinchazón elevada o erupción cutánea, empleada como término técnico sacerdotal-médico en Levítico 13-14 para el diagnóstico de enfermedades de la piel. Aparece junto a sapájat y bahéret como los tres tipos de marcas sospechosas (Lv 13:2). El español ''hinchazón'', el francés ''enflure'' y el alemán ''Schwellung'' traducen consistentemente el significado físico-dermatológico en sus siete apariciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137604, 'spa', 'Dignidad, majestad, exaltación', 'Dignidad, majestad, exaltación. Dignidad, majestad o exaltación: la elevación abstracta de rango, honor o esplendor divino. Jacob bendice a Rubén como ''preeminente en dignidad'' (Gn 49:3); los enemigos del salmista buscan derribar a alguien de su ''exaltación'' (Sal 62:4); la autoridad de los caldeos proviene ''de sí mismos'' (Hab 1:7). El francés ''grandeur'' y el español ''majestad/dignidad'' captan este registro noble.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137606, 'spa', 'Levantamiento, alzamiento', 'Levantamiento, alzamiento. El acto de levantarse o ser elevado, preservando la fuerza verbal dinámica de la raíz נָשָׂא. Génesis 4:7 habla de un ''levantamiento'' (ya sea del semblante o del perdón, asunto debatido), mientras que Job 41:25 describe el ''alzarse'' de Leviatán que hace temer a los poderosos. El francés ''exaltation'' y el alemán ''Erhebung'' conservan esta cualidad activa y eventiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137612, 'spa', 'Nombre propio de personas y un territorio árabe acaudalado', 'Nombre propio de personas y un territorio árabe acaudalado. Genealógicamente trazado a través de Cus (Gn 10:7), Joctán (Gn 10:28) y Abraham por medio de Cetura (Gn 25:3). El célebre reino cuya reina visitó a Salomón (1 Re 10:1-13). Los profetas destacan su oro (Sal 72:15), incienso (Jer 6:20; Isa 60:6) y bienes comerciales (Ez 27:22). Las ''caravanas de Saba'' en Job simbolizan esperanzas frustradas (Job 6:19).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137621, 'spa', 'Qal activo finito', 'Qal activo finito: apoderarse de personas y llevarlas cautivas en guerra o incursion. Esta es la accion militar central, usada para ejercitos que capturan poblaciones durante la conquista (Num 21:1; 1 Sam 30:2) y para Babilonia deportando a Juda (Jer 41:10). El verbo a menudo se empareja con objetos directos que nombran mujeres, ninos y ganado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137622, 'spa', 'Participio activo Qal usado como sustantivo agentivo', 'Participio activo Qal usado como sustantivo agentivo: captor, quien tiene cautivos. En las oraciones de Salomon (1 Re 8:46-50) y del Cronista (2 Cr 6:36; 30:9), Israel pide misericordia ''ante sus captores.'' La forma participial congela la accion en un rol social: quien tiene poder sobre el exiliado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137625, 'spa', 'Nifal pasivo', 'Nifal pasivo: ser tomado cautivo, sufrir captura. Este sentido expresa la experiencia de la victima y no la del agresor. Lot ''fue llevado cautivo'' (Gen 14:14); las familias de David ''habian sido llevadas cautivas'' (1 Sam 30:3, 5). El sentido se extiende tambien al ganado en contextos legales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137632, 'spa', 'Participio pasivo Qal usado como sustantivo', 'Participio pasivo Qal usado como sustantivo: un cautivo, prisionero. En Genesis 31:26, Laban acusa a Jacob de llevarse a sus hijas ''como cautivas de espada'', e Isaias 61:1 promete libertad ''a los cautivos.'' Estas formas participiales estan plenamente sustantivadas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (137659, 'spa', 'Sebuel / Subael', 'Nombre propio levítico con variantes Sebuel y Subael, que designa a dos individuos en la administración del templo de David. El primero es un descendiente gersonita de Moisés, jefe de los tesoros (1 Cr 23:16; 26:24). El segundo es hijo de Hemán, asignado a un turno de músicos del templo (1 Cr 25:4, 20).');